["{
  "claim": {
    "type": "object",
    "properties": {
      "channel": {
        "type": "string",
        "description": "Channel used to report claim",
        "title": "Channel"
      },
      "description": {
        "type": "string",
        "description": "Description of the incident",
        "title": "Incident Description"
      },
      "title": {
        "type": "string",
        "description": "Title of the incident",
        "title": "Incident Type"
      },
      "incident_type": {
        "type": "string",
        "description": "Standardized incident type",
        "enum": ["rear_end_collision", "side_impact_collision", "head_on_collision", "parking_lot_collision", "house_fire", "kitchen_fire", "electrical_fire", "burst_pipe_flood", "storm_damage", "roof_leak", "slip_and_fall", "property_injury", "product_liability", "theft_burglary", "vandalism"],
        "title": "Location Type"
      },
      "police_report_number": {
        "type": "string",
        "description": "Police report number if applicable",
        "title": "Police Report Number"
      },
      "required": [
        "incident_type",
        "location_type"
      ],
      "title": "IncidentDescription"
    },
    "InsuredObject": {
      "type": "object",
      "properties": {
        "estimated_value": {
          "type": "integer",
          "description": "Estimated monetary value in USD without currency symbol",
          "title": "Estimated Value"
        },
        "location_address": {
          "type": "string",
          "description": "Full street address where object is located or originated from",
          "title": "Location Address"
        },
        "make_model": {
          "type": "string",
          "description": "Make and model for vehicles (use standardized manufacturer names and models, or use OBJ-XXXXXX format for other objects)",
          "title": "Make Model"
        },
        "object_id": {
          "type": "string",
          "description": "Unique identifier for insured object. For vehicles, use VIN format (e.g., VIN12345678901234567). For buildings, use PROP-XXXXXX format. For liability, use LIAB-XXXXXX format. For other objects, use OBJ-XXXXXX format, where X is a digit",
          "title": "Object Id"
        },
        "object_type": {
          "type": "string",
          "description": "Type of insured object",
          "enum": ["Vehicle", "Building", "Person", "Other"]
        },
        "year": {
          "type": "integer",
          "description": "Year for vehicles or year built for buildings",
          "title": "Year"
        },
        "policy_details": {
          "type": "object",
          "properties": {
            "coverage_type": {
              "type": "string",
              "description": "Type of insurance coverage",
              "enum": ["Property", "Auto", "Liability", "Health", "Travel", "Other"]
            },
            "effective_date": {
              "type": "string",
              "description": "Policy effective start date in YYYY-MM"]

